package com.crms.controller;import com.crms.dto.AuthDtos.*;import com.crms.entity.*;import com.crms.enums.Role;import com.crms.repository.*;import com.crms.security.JwtService;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/auth") public class AuthController{private final UserRepository users;private final StudentRepository students;private final CompanyRepository companies;private final PasswordEncoder encoder;private final JwtService jwt;public AuthController(UserRepository u,StudentRepository s,CompanyRepository c,PasswordEncoder e,JwtService j){users=u;students=s;companies=c;encoder=e;jwt=j;}@PostMapping("/register")public ResponseEntity<?> register(@Valid @RequestBody RegisterRequest r){if(r.role()==Role.ADMIN||r.role()==Role.PLACEMENT_OFFICER)return ResponseEntity.badRequest().body(java.util.Map.of("message","This role requires operator provisioning"));if(users.findByEmailIgnoreCase(r.email()).isPresent())return ResponseEntity.status(HttpStatus.CONFLICT).body(java.util.Map.of("message","Email already registered"));var u=new User();u.setName(r.name());u.setEmail(r.email());u.setPassword(encoder.encode(r.password()));u.setRole(r.role());u=users.save(u);if(r.role()==Role.STUDENT){var s=new Student();s.setUser(u);students.save(s);}else{var c=new Company();c.setOwner(u);c.setName(r.name());companies.save(c);}return ResponseEntity.status(HttpStatus.CREATED).body(new UserResponse(u.getId(),u.getName(),u.getEmail(),u.getRole()));}@PostMapping("/login")public AuthResponse login(@Valid @RequestBody LoginRequest r){var u=users.findByEmailIgnoreCase(r.email()).orElseThrow(()->new org.springframework.security.authentication.BadCredentialsException("Invalid credentials"));if(!encoder.matches(r.password(),u.getPassword()))throw new org.springframework.security.authentication.BadCredentialsException("Invalid credentials");return new AuthResponse(jwt.generate(u.getId(),u.getEmail(),u.getRole().name()),new UserResponse(u.getId(),u.getName(),u.getEmail(),u.getRole()));}@GetMapping("/me")public UserResponse me(org.springframework.security.core.Authentication a){var u=users.findByEmailIgnoreCase(a.getName()).orElseThrow();return new UserResponse(u.getId(),u.getName(),u.getEmail(),u.getRole());}}
